import{_ as a,o as i,c as n,ak as s}from"./chunks/framework.DvrM7GBU.js";const b=JSON.parse('{"title":"创游世界对象 / 素材 / 组件 / 脚本关系总图","description":"","frontmatter":{},"headers":[],"relativePath":"教程资料/专题研究/创游世界对象_素材_组件_脚本关系总图.md","filePath":"教程资料/专题研究/创游世界对象_素材_组件_脚本关系总图.md","lastUpdated":1777893104000}'),e={name:"教程资料/专题研究/创游世界对象_素材_组件_脚本关系总图.md"};function r(p,l,h,d,c,o){return i(),n("div",null,[...l[0]||(l[0]=[s(`<h1 id="创游世界对象-素材-组件-脚本关系总图" tabindex="-1">创游世界对象 / 素材 / 组件 / 脚本关系总图 <a class="header-anchor" href="#创游世界对象-素材-组件-脚本关系总图" aria-label="Permalink to “创游世界对象 / 素材 / 组件 / 脚本关系总图”">​</a></h1><ul><li>分类：教程</li><li>子系统：对象结构 / 素材 / 组件 / 脚本 / UI / 广播</li><li>关键词标签：对象, 素材, 物体, 组件, 自定义组件, 脚本, UI, 广播, 系统作用域, 实例化</li><li>来源类型：官方教程 + 脚本界面截图 + 官方更新的交叉归纳</li><li>证据等级：多来源交叉归纳</li><li>完整度状态：深度整理</li><li>版本号：跨版本整理</li><li>来源文件：<code>docs/教程资料/官方教程知识索引.md</code>, <code>docs/脚本系统/脚本界面与积木知识索引.md</code>, <code>docs/引擎更新/引擎更新知识索引.md</code></li><li>来源截图编号：110222, 110225, 110352, 110404, 215522, 215524, 215530~215538, 215547, 215554, 215557</li><li>最后更新：2026-04-20</li><li>适合查询：素材和物体有何区别、组件挂在哪、脚本属于哪层、UI 如何接地图、广播为什么是核心桥梁</li></ul><h2 id="_1-文档定位" tabindex="-1">1. 文档定位 <a class="header-anchor" href="#_1-文档定位" aria-label="Permalink to “1. 文档定位”">​</a></h2><p>本文用于把目前知识库里已经分散整理出来的核心概念——对象、素材、组件、脚本、UI、广播、系统作用域——压缩成一张可理解的结构图。它不是逐页 OCR，而是面向“理解整个引擎工作方式”的总纲文档。</p><p>适合回答的问题：</p><ul><li>创游世界里的“素材”和“物体”到底有什么区别？</li><li>组件是挂在哪一层的？</li><li>脚本是属于对象、组件，还是系统？</li><li>UI 和地图逻辑是怎么接起来的？</li><li>为什么很多功能都建议用广播来做？</li></ul><hr><h2 id="_2-核心关系一句话概括" tabindex="-1">2. 核心关系一句话概括 <a class="header-anchor" href="#_2-核心关系一句话概括" aria-label="Permalink to “2. 核心关系一句话概括”">​</a></h2><p>可以先用一句话理解：</p><blockquote><p><strong>素材是模板，物体是实例，组件是能力模块，脚本是行为逻辑，广播是解耦连接器，UI 是表现与输入界面，系统层负责跨对象与跨地图的全局流程。</strong></p></blockquote><p>如果把创游世界看成搭积木：</p><ul><li><strong>素材</strong>：像预制件 / 模板</li><li><strong>物体</strong>：像被放进地图里的实际对象</li><li><strong>组件</strong>：像给对象装上的功能器官</li><li><strong>脚本</strong>：像这些器官和对象的行为规则</li><li><strong>UI</strong>：像玩家看到和点击的控制面板</li><li><strong>广播</strong>：像对象之间互相传话的机制</li><li><strong>系统</strong>：像全局导演，控制胜负、切图、音频、计时器等</li></ul><hr><h2 id="_3-总体结构图" tabindex="-1">3. 总体结构图 <a class="header-anchor" href="#_3-总体结构图" aria-label="Permalink to “3. 总体结构图”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>创游世界项目</span></span>
<span class="line"><span>├─ 地图</span></span>
<span class="line"><span>│  ├─ 地图中的物体（实例）</span></span>
<span class="line"><span>│  │  ├─ 来源：某个素材</span></span>
<span class="line"><span>│  │  ├─ 挂载：若干组件</span></span>
<span class="line"><span>│  │  └─ 执行：对象/组件相关脚本</span></span>
<span class="line"><span>│  ├─ 地图属性</span></span>
<span class="line"><span>│  ├─ 地图广播</span></span>
<span class="line"><span>│  └─ 地图级生成 / 流程逻辑</span></span>
<span class="line"><span>├─ UI</span></span>
<span class="line"><span>│  ├─ 地图UI</span></span>
<span class="line"><span>│  ├─ 操作UI</span></span>
<span class="line"><span>│  ├─ 物体UI</span></span>
<span class="line"><span>│  └─ 通过广播 / 当前UI接口与地图逻辑交互</span></span>
<span class="line"><span>├─ 系统层</span></span>
<span class="line"><span>│  ├─ 胜负流程</span></span>
<span class="line"><span>│  ├─ 切换地图</span></span>
<span class="line"><span>│  ├─ 计时器</span></span>
<span class="line"><span>│  ├─ 音频 / BGM / 声音实例</span></span>
<span class="line"><span>│  └─ 联机 / 房间 / 全局状态</span></span>
<span class="line"><span>└─ 素材库</span></span>
<span class="line"><span>   ├─ 图片 / 贴图 / 文件夹</span></span>
<span class="line"><span>   ├─ 可复用素材</span></span>
<span class="line"><span>   └─ 组件配置的模板来源</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><hr><h2 id="_4-素材与物体-模板和实例" tabindex="-1">4. 素材与物体：模板和实例 <a class="header-anchor" href="#_4-素材与物体-模板和实例" aria-label="Permalink to “4. 素材与物体：模板和实例”">​</a></h2><h3 id="_4-1-什么是素材" tabindex="-1">4.1 什么是素材 <a class="header-anchor" href="#_4-1-什么是素材" aria-label="Permalink to “4.1 什么是素材”">​</a></h3><p>根据官方教程与现有 OCR 整理，素材更接近“可复用的基础资源 / 模板定义”。</p><p>素材层通常承载：</p><ul><li>图像或贴图资源</li><li>初始属性</li><li>可挂载的组件配置</li><li>用来反复生成同类对象的基础定义</li></ul><p>这也是为什么知识库里多次出现：</p><ul><li>修改素材属性后，地图里的已有物体不一定立刻变化</li><li>需要“应用到原素材”或重新理解实例与模板的关系</li></ul><h3 id="_4-2-什么是物体" tabindex="-1">4.2 什么是物体 <a class="header-anchor" href="#_4-2-什么是物体" aria-label="Permalink to “4.2 什么是物体”">​</a></h3><p>物体是地图中的实际存在，是素材被放到地图后的实例。</p><p>物体层具有：</p><ul><li>自己当前时刻的状态</li><li>自己所在地图中的位置、层级、交互关系</li><li>挂载后的组件运行结果</li><li>运行时被脚本修改后的动态属性</li></ul><h3 id="_4-3-为什么修改素材不一定影响地图中的物体" tabindex="-1">4.3 为什么修改素材不一定影响地图中的物体 <a class="header-anchor" href="#_4-3-为什么修改素材不一定影响地图中的物体" aria-label="Permalink to “4.3 为什么修改素材不一定影响地图中的物体”">​</a></h3><p>因为很多情况下，地图里的物体不是“实时引用素材面板”，而是已经带着当时的配置被实例化出来了。</p><p>这意味着：</p><ul><li><strong>素材</strong>更像“出生模板”</li><li><strong>物体</strong>更像“出生后的个体”</li></ul><p>所以在项目设计上要特别注意：</p><ul><li>想批量复用某种能力时，要先把组件和通用配置收敛到素材模板层</li><li>想改某个特定对象时，要确认你改的是实例，还是模板</li></ul><hr><h2 id="_5-组件-对象能力的装配层" tabindex="-1">5. 组件：对象能力的装配层 <a class="header-anchor" href="#_5-组件-对象能力的装配层" aria-label="Permalink to “5. 组件：对象能力的装配层”">​</a></h2><h3 id="_5-1-组件的本质" tabindex="-1">5.1 组件的本质 <a class="header-anchor" href="#_5-1-组件的本质" aria-label="Permalink to “5.1 组件的本质”">​</a></h3><p>组件是对象的功能模块。它决定这个对象“能做什么”。</p><p>例如：</p><ul><li>生命组件：能有血量、受伤、死亡</li><li>子弹组件：能发射、碰撞、造成效果</li><li>货币组件：能记录货币数值</li><li>近战武器组件：能进行近战攻击</li><li>粒子特效组件：能产生视觉效果</li><li>UI 相关组件：能参与界面显示或交互</li></ul><h3 id="_5-2-为什么组件重要" tabindex="-1">5.2 为什么组件重要 <a class="header-anchor" href="#_5-2-为什么组件重要" aria-label="Permalink to “5.2 为什么组件重要”">​</a></h3><p>因为创游世界不是纯代码驱动的系统，而是明显偏向：</p><blockquote><p><strong>对象 = 基础实体，组件 = 能力组合，脚本 = 行为编排</strong></p></blockquote><p>这意味着你做功能时，不是从“写一大段代码”开始，而是先判断：</p><ol><li>这个功能属于哪个对象？</li><li>这个对象需要哪些组件？</li><li>脚本应该绑定在哪个层级、响应什么触发时机？</li></ol><h3 id="_5-3-自定义组件的意义" tabindex="-1">5.3 自定义组件的意义 <a class="header-anchor" href="#_5-3-自定义组件的意义" aria-label="Permalink to “5.3 自定义组件的意义”">​</a></h3><p>自定义组件进一步把“能力模块化”推进了一步。它不只是官方预置组件的补充，更像是你自己定义的、可复用的小系统。</p><p>它通常包含：</p><ul><li>属性</li><li>指令</li><li>触发时机 / 事件入口</li></ul><p>其价值在于：</p><ul><li>复用</li><li>统一接口</li><li>降低重复搭积木成本</li><li>让多个对象共享同一行为协议</li></ul><hr><h2 id="_6-脚本-行为逻辑与数据流" tabindex="-1">6. 脚本：行为逻辑与数据流 <a class="header-anchor" href="#_6-脚本-行为逻辑与数据流" aria-label="Permalink to “6. 脚本：行为逻辑与数据流”">​</a></h2><h3 id="_6-1-脚本不是孤立存在的" tabindex="-1">6.1 脚本不是孤立存在的 <a class="header-anchor" href="#_6-1-脚本不是孤立存在的" aria-label="Permalink to “6.1 脚本不是孤立存在的”">​</a></h3><p>脚本通常依附在某个上下文中执行，例如：</p><ul><li>对象脚本</li><li>组件相关脚本</li><li>地图脚本</li><li>系统脚本</li><li>UI 侧逻辑</li></ul><p>所以脚本不是一个脱离场景的“代码文件”，而是：</p><blockquote><p><strong>在特定作用域里，围绕某个对象/组件/系统能力执行的行为描述。</strong></p></blockquote><h3 id="_6-2-脚本真正解决什么问题" tabindex="-1">6.2 脚本真正解决什么问题 <a class="header-anchor" href="#_6-2-脚本真正解决什么问题" aria-label="Permalink to “6.2 脚本真正解决什么问题”">​</a></h3><p>脚本主要负责：</p><ul><li>响应事件</li><li>读写数据</li><li>调用组件能力</li><li>修改对象状态</li><li>通知 UI</li><li>驱动流程推进</li></ul><p>也就是说：</p><ul><li>组件提供“能做什么”</li><li>脚本决定“什么时候做、怎么做、做到什么程度”</li></ul><h3 id="_6-3-常见错误理解" tabindex="-1">6.3 常见错误理解 <a class="header-anchor" href="#_6-3-常见错误理解" aria-label="Permalink to “6.3 常见错误理解”">​</a></h3><p>一个常见误区是把脚本当成唯一核心。</p><p>更准确地说，创游世界里真正的核心是：</p><blockquote><p><strong>对象结构 + 组件装配 + 脚本编排 + 作用域数据流</strong></p></blockquote><p>脚本只是其中一环。</p><hr><h2 id="_7-作用域-状态应该放在哪里" tabindex="-1">7. 作用域：状态应该放在哪里 <a class="header-anchor" href="#_7-作用域-状态应该放在哪里" aria-label="Permalink to “7. 作用域：状态应该放在哪里”">​</a></h2><p>根据已有脚本资料，可把常用数据位置粗略分成四层：</p><h3 id="_7-1-局部层" tabindex="-1">7.1 局部层 <a class="header-anchor" href="#_7-1-局部层" aria-label="Permalink to “7.1 局部层”">​</a></h3><ul><li>临时计算</li><li>一次流程中的中间变量</li><li>不需要跨对象共享的数据</li></ul><h3 id="_7-2-自身层" tabindex="-1">7.2 自身层 <a class="header-anchor" href="#_7-2-自身层" aria-label="Permalink to “7.2 自身层”">​</a></h3><ul><li>某个对象自己的状态</li><li>例如：当前血量、是否翻滚中、攻击冷却、是否已拾取</li></ul><h3 id="_7-3-地图层" tabindex="-1">7.3 地图层 <a class="header-anchor" href="#_7-3-地图层" aria-label="Permalink to “7.3 地图层”">​</a></h3><ul><li>同一地图里多个对象共享的数据</li><li>例如：当前波次、地图倒计时、地图级开关、地图内货币池</li></ul><h3 id="_7-4-系统层" tabindex="-1">7.4 系统层 <a class="header-anchor" href="#_7-4-系统层" aria-label="Permalink to “7.4 系统层”">​</a></h3><ul><li>跨地图、跨流程、全局控制数据</li><li>例如：胜负、切图、总计时器、系统音频、联机房间级状态</li></ul><h3 id="_7-5-一个实用原则" tabindex="-1">7.5 一个实用原则 <a class="header-anchor" href="#_7-5-一个实用原则" aria-label="Permalink to “7.5 一个实用原则”">​</a></h3><p>如果你不知道某个变量应该放哪里，可以先问：</p><ul><li>它只在一段逻辑里短暂使用吗？→ 局部</li><li>它只属于某个物体吗？→ 自身</li><li>它要让地图里很多对象都能读到吗？→ 地图</li><li>它要控制整局流程或跨地图逻辑吗？→ 系统</li></ul><hr><h2 id="_8-ui-表现层与输入层" tabindex="-1">8. UI：表现层与输入层 <a class="header-anchor" href="#_8-ui-表现层与输入层" aria-label="Permalink to “8. UI：表现层与输入层”">​</a></h2><h3 id="_8-1-ui-不是地图逻辑本体" tabindex="-1">8.1 UI 不是地图逻辑本体 <a class="header-anchor" href="#_8-1-ui-不是地图逻辑本体" aria-label="Permalink to “8.1 UI 不是地图逻辑本体”">​</a></h3><p>UI 更适合做：</p><ul><li>显示信息</li><li>接收点击 / 交互输入</li><li>呈现状态变化</li><li>作为玩家和系统之间的中介面板</li></ul><p>不推荐让 UI 直接承担太多核心业务逻辑。</p><h3 id="_8-2-ui-与地图逻辑的推荐关系" tabindex="-1">8.2 UI 与地图逻辑的推荐关系 <a class="header-anchor" href="#_8-2-ui-与地图逻辑的推荐关系" aria-label="Permalink to “8.2 UI 与地图逻辑的推荐关系”">​</a></h3><p>推荐结构通常是：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>玩家操作UI</span></span>
<span class="line"><span>→ UI 触发事件</span></span>
<span class="line"><span>→ 广播 / 调用接口</span></span>
<span class="line"><span>→ 地图或对象逻辑处理</span></span>
<span class="line"><span>→ 修改状态</span></span>
<span class="line"><span>→ UI 刷新显示</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>这样做的好处：</p><ul><li>UI 更容易替换</li><li>地图逻辑更稳定</li><li>联机 / 本地切换时更容易兼容</li><li>不会把核心系统锁死在某个界面上</li></ul><h3 id="_8-3-三种-ui-可以怎么理解" tabindex="-1">8.3 三种 UI 可以怎么理解 <a class="header-anchor" href="#_8-3-三种-ui-可以怎么理解" aria-label="Permalink to “8.3 三种 UI 可以怎么理解”">​</a></h3><ul><li><strong>地图UI</strong>：更偏场景级界面</li><li><strong>操作UI</strong>：更偏玩家操作入口</li><li><strong>物体UI</strong>：更偏绑定到对象或对象上下文的界面</li></ul><hr><h2 id="_9-广播-对象之间的解耦连接器" tabindex="-1">9. 广播：对象之间的解耦连接器 <a class="header-anchor" href="#_9-广播-对象之间的解耦连接器" aria-label="Permalink to “9. 广播：对象之间的解耦连接器”">​</a></h2><p>广播在创游世界里非常关键，因为很多系统都不适合硬绑死调用路径。</p><p>广播适合解决：</p><ul><li>UI 通知地图逻辑</li><li>地图通知若干对象同步变化</li><li>系统事件分发</li><li>降低对象之间的直接依赖</li></ul><p>例如：</p><ul><li>点击按钮后，不让 UI 直接改某个敌人的生命值</li><li>而是 UI 发“开始战斗 / 使用技能 / 请求购买”广播</li><li>真正的处理逻辑由地图或目标对象决定</li></ul><p>这样做的优点：</p><ul><li>降耦合</li><li>更适合多人协作</li><li>更适合后期重构</li><li>更容易复用同一套功能</li></ul><hr><h2 id="_10-一个完整功能是如何跑起来的" tabindex="-1">10. 一个完整功能是如何跑起来的 <a class="header-anchor" href="#_10-一个完整功能是如何跑起来的" aria-label="Permalink to “10. 一个完整功能是如何跑起来的”">​</a></h2><p>以“点击按钮购买道具”为例，可以抽象成：</p><h3 id="第一步-素材准备" tabindex="-1">第一步：素材准备 <a class="header-anchor" href="#第一步-素材准备" aria-label="Permalink to “第一步：素材准备”">​</a></h3><ul><li>定义一个可购买道具素材</li><li>挂载需要的组件</li></ul><h3 id="第二步-实例进入地图" tabindex="-1">第二步：实例进入地图 <a class="header-anchor" href="#第二步-实例进入地图" aria-label="Permalink to “第二步：实例进入地图”">​</a></h3><ul><li>地图中出现商店物体或购买入口物体</li></ul><h3 id="第三步-ui-提供按钮" tabindex="-1">第三步：UI 提供按钮 <a class="header-anchor" href="#第三步-ui-提供按钮" aria-label="Permalink to “第三步：UI 提供按钮”">​</a></h3><ul><li>玩家在 UI 中点击“购买”</li></ul><h3 id="第四步-通过广播或接口通知逻辑层" tabindex="-1">第四步：通过广播或接口通知逻辑层 <a class="header-anchor" href="#第四步-通过广播或接口通知逻辑层" aria-label="Permalink to “第四步：通过广播或接口通知逻辑层”">​</a></h3><ul><li>UI 发出“请求购买某道具”的信号</li></ul><h3 id="第五步-地图-系统脚本校验" tabindex="-1">第五步：地图 / 系统脚本校验 <a class="header-anchor" href="#第五步-地图-系统脚本校验" aria-label="Permalink to “第五步：地图 / 系统脚本校验”">​</a></h3><ul><li>检查货币是否足够</li><li>检查是否允许购买</li><li>更新库存或生成道具</li></ul><h3 id="第六步-对象与状态更新" tabindex="-1">第六步：对象与状态更新 <a class="header-anchor" href="#第六步-对象与状态更新" aria-label="Permalink to “第六步：对象与状态更新”">​</a></h3><ul><li>扣除货币</li><li>生成物体 / 添加道具</li><li>更新自身或地图数据</li></ul><h3 id="第七步-ui-刷新" tabindex="-1">第七步：UI 刷新 <a class="header-anchor" href="#第七步-ui-刷新" aria-label="Permalink to “第七步：UI 刷新”">​</a></h3><ul><li>价格、货币数、背包显示同步变化</li></ul><p>这个流程里没有一个点是单独孤立的，而是涉及：</p><ul><li>素材</li><li>物体</li><li>组件</li><li>脚本</li><li>UI</li><li>广播</li><li>作用域数据</li></ul><p>这就是为什么建立“关系总图”非常重要。</p><hr><h2 id="_11-建知识库时最值得固定下来的主线" tabindex="-1">11. 建知识库时最值得固定下来的主线 <a class="header-anchor" href="#_11-建知识库时最值得固定下来的主线" aria-label="Permalink to “11. 建知识库时最值得固定下来的主线”">​</a></h2><p>如果以后继续增强知识库，最值得一直坚持的主线是：</p><h3 id="主线-a-模板与实例" tabindex="-1">主线 A：模板与实例 <a class="header-anchor" href="#主线-a-模板与实例" aria-label="Permalink to “主线 A：模板与实例”">​</a></h3><ul><li>素材</li><li>物体</li><li>应用到原素材</li><li>实例化差异</li></ul><h3 id="主线-b-能力装配" tabindex="-1">主线 B：能力装配 <a class="header-anchor" href="#主线-b-能力装配" aria-label="Permalink to “主线 B：能力装配”">​</a></h3><ul><li>官方组件</li><li>自定义组件</li><li>组件分类</li><li>组件边界</li></ul><h3 id="主线-c-行为与数据流" tabindex="-1">主线 C：行为与数据流 <a class="header-anchor" href="#主线-c-行为与数据流" aria-label="Permalink to “主线 C：行为与数据流”">​</a></h3><ul><li>指令</li><li>脚本</li><li>触发时机</li><li>变量作用域</li><li>地图与系统状态</li></ul><h3 id="主线-d-界面与交互" tabindex="-1">主线 D：界面与交互 <a class="header-anchor" href="#主线-d-界面与交互" aria-label="Permalink to “主线 D：界面与交互”">​</a></h3><ul><li>UI 分类</li><li>当前 UI</li><li>物体 UI</li><li>UI 与地图的通信方式</li></ul><h3 id="主线-e-工程与版本" tabindex="-1">主线 E：工程与版本 <a class="header-anchor" href="#主线-e-工程与版本" aria-label="Permalink to “主线 E：工程与版本”">​</a></h3><ul><li>引擎更新</li><li>联机 UI 演进</li><li>调试工具</li><li>不同版本下功能差异</li></ul><hr><h2 id="_12-可作为-ai-检索的关键词" tabindex="-1">12. 可作为 AI 检索的关键词 <a class="header-anchor" href="#_12-可作为-ai-检索的关键词" aria-label="Permalink to “12. 可作为 AI 检索的关键词”">​</a></h2><ul><li>对象</li><li>素材</li><li>物体</li><li>组件</li><li>自定义组件</li><li>指令</li><li>脚本</li><li>触发时机</li><li>UI</li><li>地图UI</li><li>操作UI</li><li>物体UI</li><li>广播</li><li>地图广播</li><li>系统作用域</li><li>地图作用域</li><li>实例化</li><li>应用到原素材</li><li>数据流</li><li>状态分层</li><li>架构</li></ul><hr><h2 id="_13-证据等级与来源说明" tabindex="-1">13. 证据等级与来源说明 <a class="header-anchor" href="#_13-证据等级与来源说明" aria-label="Permalink to “13. 证据等级与来源说明”">​</a></h2><ul><li><p>证据等级：多来源交叉归纳</p></li><li><p>来源说明：官方教程 + 脚本界面截图 + 引擎更新说明交叉归纳</p></li><li><p>主要来源：</p><ul><li><code>docs/教程资料/官方教程知识索引.md</code></li><li><code>docs/脚本系统/脚本界面与积木知识索引.md</code></li><li><code>docs/教程资料/专题研究/素材实例化与地图物体关系解析.md</code></li><li><code>docs/教程资料/专题研究/素材系统与组件挂载解析.md</code></li><li><code>docs/教程资料/专题研究/广播机制深度解析.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/创游世界脚本实战架构入门.md</code></li></ul></li><li><p>完整度状态：深度整理</p></li></ul><hr><h2 id="_14-关联阅读" tabindex="-1">14. 关联阅读 <a class="header-anchor" href="#_14-关联阅读" aria-label="Permalink to “14. 关联阅读”">​</a></h2><ul><li><code>docs/教程资料/专题研究/素材实例化与地图物体关系解析.md</code></li><li><code>docs/教程资料/专题研究/素材系统与组件挂载解析.md</code></li><li><code>docs/教程资料/专题研究/广播机制深度解析.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/元信息/创游世界术语表.md</code></li></ul><h2 id="_15-后续可继续补的方向" tabindex="-1">15. 后续可继续补的方向 <a class="header-anchor" href="#_15-后续可继续补的方向" aria-label="Permalink to “15. 后续可继续补的方向”">​</a></h2><ol><li>把“组件分类”展开为单独知识图谱</li><li>把“脚本作用域”配成更多实战案例</li><li>把“UI → 广播 → 地图 → 系统”的数据流做成模板库</li><li>把“素材模板 → 地图实例”的常见误区列成 FAQ</li></ol>`,147)])])}const u=a(e,[["render",r]]);export{b as __pageData,u as default};
